module.exports="  const cards=Array.from(document.querySelectorAll('.controlcard[data-piece]'));\n  function selectPiece(piece){\n    cards.forEach(card=>card.classList.toggle('mobile-active',card.dataset.piece===piece));\n    updateActiveProduct(piece);\n    nav.querySelectorAll('button').forEach(button=>{\n      const active=button.dataset.tab===piece;\n      button.classList.toggle('active',active);\n      button.setAttribute('aria-pressed',String(active));\n    });\n    document.querySelector('.sidebar').classList.remove('show-summary');\n    const summary=document.getElementById('summaryToggle');\n    summary.textContent='Show Color Summary';summary.setAttribute('aria-expanded','false');\n  }\n  nav.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>selectPiece(b.dataset.tab)));\n  cards.forEach(card=>card.addEventListener('pointerdown',()=>updateActiveProduct(card.dataset.piece)));\n  document.querySelectorAll('.previewcard').forEach((card,i)=>card.addEventListener('pointerdown',()=>updateActiveProduct(i===0?'kit':'short')));\n  document.getElementById('summaryToggle').addEventListener('click',function(){\n    const shown=document.querySelector('.sidebar').classList.toggle('show-summary');\n    this.textContent=shown?'Hide Color Summary':'Show Color Summary';\n    this.setAttribute('aria-expanded',String(shown));\n  });\n  selectPiece('kit');\n}\nsetupMobileInterface();\n</script>\n<script>\n/* Approved original SVG-derived photos and masks, with true grayscale Gaussian 2px feather.\n   All colors are inherited from existing panel colors; no duplicate palette. */\nconst APPROVED_LOGO_ASSETS=[{\"name\":\"Enhanced Heat Transfer\",\"image\":\"data:image/png;base64,";